  row=self.capture.capture(frame,time_s,extra=extra)
  event=self.evidence_reader.readline()
  if not event:raise RuntimeError('Missing original captured observation packet')
  self.last_evidence=json.loads(event)
  if self.last_evidence['original_frame']!=frame:raise RuntimeError('Original evidence frame mismatch')
  if callable(observations):observations=observations(row,self.last_evidence)
  missing=[name for name in self.channels if observations.get(name) is None]
  if missing:raise ValueError('Mandatory observation unavailable: '+','.join(missing))
  for name,f in self.channels.items():f.write(json.dumps(dict(time_s=time_s,value=observations[name]))+'\n')
  for q,encoder in zip(self.cameras,self.encoders):
   image=q.get(timeout=30)
   while image.frame<frame:image=q.get(timeout=30)
   if image.frame!=frame:raise RuntimeError('Original camera timestamp mismatch')
   encoder.stdin.write(bytes(image.raw_data))
  self.frame_map.write(json.dumps(dict(video_frame=self.frames,carla_frame=frame,time_s=time_s))+'\n');self.frames+=1
  return row
 def close(self):
  if not self.closed:self.closed=True;self.close_errors+=self.resources.close()
  return self.close_errors
 def result_fields(self):
  return dict(trace_reference='trace.jsonl',video_frame_map_reference='video_frame_map.jsonl',video_references=['camera-'+str(i)+'.webm' for i in range(len(self.cameras))],recording_evidence=self.evidence,recording_description=self.description)

"""Small, standard-library-only file and identity helpers."""
import hashlib
import json
import os
import re
import tempfile
from pathlib import Path, PurePosixPath

SETS = ('demo-train', 'demo-test', 'held-out', 'full-train', 'full-test')
SKILLS = ('law-grounded-cells', 'law-relevance-mapping', 'law-cell-bindings',
          'law-judgment-observables', 'scenario-coverage-cases', 'carla-scenario-build')


def read(path):
    return json.loads(Path(path).read_text())


def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(',', ':'),
                                     ensure_ascii=False).encode()).hexdigest()


def sha(path):
    h = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b''):
            h.update(chunk)
    return h.hexdigest()


def write(path, value):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=path.parent, prefix='.' + path.name)
    try:
        with os.fdopen(fd, 'w') as stream:
            stream.write(json.dumps(value, indent=2, ensure_ascii=False) + '\n')
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(tmp, path)
    finally:
        if Path(tmp).exists():
            Path(tmp).unlink()


def name(value):
    if not isinstance(value, str) or not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_.-]*', value):
        raise ValueError('Unsafe identifier: ' + str(value))
    return value


def within(root, relative):
    raw = PurePosixPath(str(relative))
    if raw.is_absolute() or not raw.parts or any(p in ('..', '.') for p in raw.parts) or '\\' in str(relative):
        raise ValueError('Expected a relative contained path: ' + str(relative))
    root = Path(root).resolve()
    path = root.joinpath(*raw.parts)
    # A symlink into the tree is also forbidden: portable packages carry files.
    for parent in [path, *path.parents]:
        if parent == root:
            break
        if parent.is_symlink():
            raise ValueError('Symlink in package: ' + str(relative))
    if root not in path.resolve().parents:
        raise ValueError('Path escapes root: ' + str(relative))
    return path


def assignment_id(a, role):
    # Demo/full overlap must not create a second implementation.
    return '__'.join(name(str(x)) for x in (role, a['cell_id'], a['law_id'], a['actor']))


def tree(root):
    result = {}
    for path in sorted(Path(root).rglob('*')):
        rel = path.relative_to(root)
        if any(p in ('.git', '__pycache__', '.pytest_cache') for p in rel.parts) or path.suffix == '.pyc':
            continue
        within(root, rel.as_posix())
        if path.is_file():
            result[rel.as_posix()] = sha(path)
    return result

"""Portable result/geometry checks. Used by CPU fixtures and live finalization."""
import math
from pathlib import Path
from .common import read


def validate_result(directory, result):
    directory=Path(directory)
    for key in ('setup_confirmed','behavior_attempted','maneuver_completed'):
        if result.get(key) is not True:raise ValueError('Incomplete '+key)
    if result.get('physical_failure_flags'):raise ValueError('Physical/capture failures remain')
    videos=result.get('video_references')
    if not videos or any(not isinstance(v,str) for v in videos):raise ValueError('Encoded video file paths required')
    for name in videos:
        path=(directory/name).resolve()
        if directory.resolve() not in path.parents or not path.is_file():raise ValueError('Missing contained video')
    for key in ('trace_reference','video_frame_map_reference'):
        if not isinstance(result.get(key),str) or not (directory/result[key]).is_file():raise ValueError('Missing '+key)
    if not result.get('target_checks'):raise ValueError('Missing measured target checks')
    return True


def channel_samples(samples, expected_frames):
    if len(samples)!=expected_frames:raise ValueError('Incomplete channel history')
    for sample in samples:
        if sample.get('value') is None or sample.get('missing_capability'):raise ValueError('Unimplemented mandatory channel')
        if not isinstance(sample.get('time_s'),(int,float)) or not math.isfinite(sample['time_s']):raise ValueError('Invalid time')
    if any(a['time_s']>=b['time_s'] for a,b in zip(samples,samples[1:])):raise ValueError('Nonincreasing times')
    return True


def route_contained(vertices, polygon):
    """All supplied footprint vertices must lie in the authored reference polygon."""
    def inside(p):
        x,y=p;odd=False
        for a,b in zip(polygon,polygon[1:]+polygon[:1]):
            cross=(x-a[0])*(b[1]-a[1])-(y-a[1])*(b[0]-a[0])
            if abs(cross)<1e-9 and min(a[0],b[0])<=x<=max(a[0],b[0]) and min(a[1],b[1])<=y<=max(a[1],b[1]):return True
            if (a[1]>y)!=(b[1]>y) and x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0]:odd=not odd
        return odd
    if not polygon or not vertices or not all(inside(v) for v in vertices):raise ValueError('Footprint outside reference region')
    return True
